const items = $input.all();

function stableStringify(obj) {
  if (obj === null || typeof obj !== 'object') return JSON.stringify(obj);
  if (Array.isArray(obj)) return '[' + obj.map(stableStringify).join(',') + ']';
  const keys = Object.keys(obj).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + stableStringify(obj[k])).join(',') + '}';
}

// Shows exactly what text was inserted/removed instead of dumping full before/after blobs.
function stringDiff(oldStr, newStr) {
  let start = 0;
  const maxStart = Math.min(oldStr.length, newStr.length);
  while (start < maxStart && oldStr[start] === newStr[start]) start++;

  let endOld = oldStr.length, endNew = newStr.length;
  while (endOld > start && endNew > start && oldStr[endOld - 1] === newStr[endNew - 1]) {
    endOld--; endNew--;
  }

  const removed = oldStr.slice(start, endOld);
  const added = newStr.slice(start, endNew);

  if (!removed && added) return `added text: "${added}"`;
  if (removed && !added) return `removed text: "${removed}"`;
  if (removed && added) return `replaced "${removed}" with "${added}"`;
  return 'value changed (no textual diff detected)';
}

function trim(v, max = 120) {
  if (v === undefined) return 'undefined';
  return v.length > max ? v.slice(0, max) + '\u2026' : v;
}

// Fields n8n auto-touches on nearly every save/drag with no real semantic change.
const NODE_NOISE_KEYS = new Set(['position', 'versionCounter', 'id', 'webhookId']);

// n8n masks/rotates credential IDs for credentials the API caller doesn't directly
// own or that are shared/placeholder ("test-temp-XXX") — the id can differ on every
// single fetch even though the actual assignment never changed. Only the credential
// *name* is a stable signal of a real reassignment, so we compare on name only.
function normalizeCredentials(creds) {
  if (!creds || typeof creds !== 'object') return creds;
  const out = {};
  Object.keys(creds).sort().forEach(type => {
    const c = creds[type] || {};
    out[type] = { name: c.name };
  });
  return out;
}

function nodesEqualIgnoringNoise(oldNode, newNode) {
  const stripNoise = (n) => {
    const c = { ...n };
    NODE_NOISE_KEYS.forEach(k => delete c[k]);
    if (c.credentials) c.credentials = normalizeCredentials(c.credentials);
    return c;
  };
  return stableStringify(stripNoise(oldNode)) === stableStringify(stripNoise(newNode));
}

function diffParams(oldNode, newNode) {
  const changes = [];
  const oldParams = (oldNode && oldNode.parameters) || {};
  const newParams = (newNode && newNode.parameters) || {};
  const allKeys = new Set([...Object.keys(oldParams), ...Object.keys(newParams)]);

  allKeys.forEach(key => {
    const oldRaw = oldParams[key];
    const newRaw = newParams[key];
    const oldStr = stableStringify(oldRaw);
    const newStr = stableStringify(newRaw);
    if (oldStr === newStr) return;

    if (typeof oldRaw === 'string' && typeof newRaw === 'string') {
      changes.push(`${key}: ${stringDiff(oldRaw, newRaw)}`);
    } else {
      changes.push(`${key}: ${trim(oldStr)} \u2192 ${trim(newStr)}`);
    }
  });

  return changes;
}

function diffNodeFields(oldNode, newNode) {
  const changes = [];
  const keys = new Set([...Object.keys(oldNode || {}), ...Object.keys(newNode || {})]);

  keys.forEach(key => {
    if (key === 'parameters' || NODE_NOISE_KEYS.has(key)) return;
    const oldVal = oldNode ? oldNode[key] : undefined;
    const newVal = newNode ? newNode[key] : undefined;
    const oldStr = stableStringify(oldVal);
    const newStr = stableStringify(newVal);
    if (oldStr === newStr) return;

    if (key === 'disabled') {
      changes.push(newVal === true ? 'Node deactivated (disabled in n8n).' : 'Node re-activated (enabled in n8n).');
    } else if (key === 'notes') {
      if (typeof oldVal === 'string' && typeof newVal === 'string') {
        changes.push(`notes: ${stringDiff(oldVal, newVal)}`);
      } else {
        changes.push('notes updated.');
      }
    } else if (key === 'credentials') {
      const oldNorm = normalizeCredentials(oldVal);
      const newNorm = normalizeCredentials(newVal);
      if (stableStringify(oldNorm) !== stableStringify(newNorm)) {
        changes.push('credentials assignment changed.');
      }
      // else: only the (rotating/masked) id differed — not a real change, skip.
    } else {
      changes.push(`${key}: ${trim(oldStr)} \u2192 ${trim(newStr)}`);
    }
  });

  return changes;
}

// ---- Connection (edge) level diffing ----
function flattenConnections(connections) {
  const edges = [];
  Object.keys(connections || {}).forEach(sourceName => {
    const outputTypes = connections[sourceName] || {};
    Object.keys(outputTypes).forEach(outputType => {
      const branches = outputTypes[outputType] || [];
      branches.forEach((branch, outputIndex) => {
        (branch || []).forEach(conn => {
          if (!conn) return;
          edges.push({
            source: sourceName,
            outputType,
            outputIndex,
            target: conn.node,
            targetInputType: conn.type,
            targetInputIndex: conn.index
          });
        });
      });
    });
  });
  return edges;
}

function edgeKey(e) {
  return `${e.source}|${e.outputType}|${e.outputIndex}|${e.target}|${e.targetInputType}|${e.targetInputIndex}`;
}

function diffConnections(oldConn, newConn) {
  const oldEdges = flattenConnections(oldConn);
  const newEdges = flattenConnections(newConn);
  const oldMap = new Map(oldEdges.map(e => [edgeKey(e), e]));
  const newMap = new Map(newEdges.map(e => [edgeKey(e), e]));

  const added = [];
  const removed = [];

  newMap.forEach((e, k) => {
    if (!oldMap.has(k)) added.push(`"${e.source}" \u2192 "${e.target}"`);
  });
  oldMap.forEach((e, k) => {
    if (!newMap.has(k)) removed.push(`"${e.source}" \u2192 "${e.target}"`);
  });

  return { added, removed };
}

function summarizeChanges(oldWf, newWf) {
  if (!oldWf) return ['New workflow file (no previous version found in GitLab).'];
  const lines = [];

  const oldNodes = Array.isArray(oldWf.nodes) ? oldWf.nodes : [];
  const newNodes = Array.isArray(newWf.nodes) ? newWf.nodes : [];
  const oldById = new Map(oldNodes.map(n => [n.name || n.id, n]));
  const newById = new Map(newNodes.map(n => [n.name || n.id, n]));

  const added = [];
  const removed = [];
  const modified = [];

  newById.forEach((node, id) => {
    if (!oldById.has(id)) {
      added.push(`${node.name || id} (${node.type || 'unknown type'})`);
    } else {
      const oldNode = oldById.get(id);
      if (!nodesEqualIgnoringNoise(oldNode, node)) {
        const paramChanges = diffParams(oldNode, node);
        const fieldChanges = diffNodeFields(oldNode, node);
        modified.push({ name: node.name || id, type: node.type || 'unknown type', paramChanges, fieldChanges });
      }
    }
  });

  oldById.forEach((node, id) => {
    if (!newById.has(id)) {
      removed.push(`${node.name || id} (${node.type || 'unknown type'})`);
    }
  });

  if (added.length) lines.push(`Added nodes: ${added.join(', ')}`);
  if (removed.length) lines.push(`Removed nodes: ${removed.join(', ')}`);
  if (modified.length) {
    modified.forEach(m => {
      lines.push(`Modified node "${m.name}" (${m.type}):`);
      const allChanges = [...m.fieldChanges, ...m.paramChanges];
      if (allChanges.length) {
        allChanges.forEach(c => lines.push(`  - ${c}`));
      } else {
        lines.push('  - value changed (details not detected)');
      }
    });
  }

  const connDiff = diffConnections(oldWf.connections || {}, newWf.connections || {});
  if (connDiff.added.length) lines.push(`Added connections: ${connDiff.added.join(', ')}`);
  if (connDiff.removed.length) lines.push(`Removed connections: ${connDiff.removed.join(', ')}`);

  const skip = new Set(['nodes', 'connections']);
  Object.keys(newWf || {}).forEach(key => {
    if (skip.has(key)) return;
    const oldVal = oldWf ? oldWf[key] : undefined;
    const newVal = newWf[key];
    if (stableStringify(oldVal) !== stableStringify(newVal)) {
      lines.push(`Field "${key}" changed.`);
    }
  });

  if (lines.length === 0) lines.push('Workflow content changed (no structural diff detected \u2014 likely formatting/metadata only).');

  return lines;
}

// DÜZƏLİŞ: eyni slug-a sahib iki fərqli workflow olduqda (məs. "check_webhooks_backup"
// və "check_webhooks-backup" -> hər ikisi "check-webhooks-backup" slug-una düşür) onlar
// eyni GitLab faylını "tennis-match" kimi bir-birinin üzərinə yazır və isDifferent
// heç vaxt sabitləşmir. Bunu erkən aşkarlamaq üçün xəbərdarlıq/atma əlavə edirik.
const perItem3All = $('per Item3').all();
const slugCounts = {};
perItem3All.forEach(p => {
  const s = p.json.slug;
  if (!s) return;
  slugCounts[s] = (slugCounts[s] || 0) + 1;
});
const duplicateSlugs = Object.keys(slugCounts).filter(s => slugCounts[s] > 1);
if (duplicateSlugs.length) {
  throw new Error(
    `Slug collision detected — multiple workflows map to the same GitLab file and will ` +
    `overwrite each other forever: ${duplicateSlugs.join(', ')}. Rename one of the ` +
    `colliding n8n workflows so their slugs become unique before syncing.`
  );
}

return items.map((item, index) => {
  // DÜZƏLİŞ: Əgər item artıq özündə n8nWorkflow daşıyırsa (loop-back), birbaşa onu götürürük,
  // əks halda (ilk keçid) Prepare workflow-dan sabit açara (projectId/slug) görə uyğunlaşdırırıq.
  // İndex ilə uyğunlaşdırma etibarsızdır, çünki aradakı HTTP node batching +
  // continueRegularOutput ilə işlədiyi üçün sıra execution-lar arası fərqli ola bilər.
  const matchByKey = (arr) => arr.find(p =>
    (item.json.projectId !== undefined && p.json.projectId === item.json.projectId) ||
    (item.json.slug !== undefined && p.json.slug === item.json.slug)
  );

  const n8nWorkflow = item.json.n8nWorkflow
    || matchByKey(perItem3All)?.json
    || perItem3All[index].json;

  const projectId = item.json.projectId
    || matchByKey(perItem3All)?.json?.projectId
    || perItem3All[index].json.projectId;

  const workflowName = n8nWorkflow.originalName || n8nWorkflow.name;

  let gitlabContent;
  try {
    // n8n HTTP Request node fullResponse:true olduqda cavab item.json.body-də gəlir,
    // item.json.data-da yox — əvvəlki kod həmişə data axtardığı üçün gitlabContent
    // həmişə null qalırdı və hər fayl "yeni" (isDifferent=true) kimi görünürdü.
    const rawData = item.json.body !== undefined ? item.json.body : item.json.data;
    gitlabContent = typeof rawData === 'string'
      ? JSON.parse(rawData)
      : rawData;
  } catch (e) {
    gitlabContent = null;
  }

  const volatileKeys = [
    'updatedAt', 'createdAt', 'versionId', 'activeVersionId', 'activeVersion',
    'shared', 'meta', 'slug', 'originalName', 'id', 'triggerCount',
    'isArchived', 'active', 'tags', 'pinData', 'staticData', 'versionCounter'
  ];

  const stripVolatile = (wf) => {
    if (!wf) return null;
    const clean = { ...wf };
    volatileKeys.forEach(k => delete clean[k]);
    return clean;
  };

  const stripNodeNoise = (wf) => {
    if (!wf || !Array.isArray(wf.nodes)) return wf;
    const clone = { ...wf };
    clone.nodes = wf.nodes.map(node => {
      const n = { ...node };
      NODE_NOISE_KEYS.forEach(k => delete n[k]);
      return n;
    });
    return clone;
  };

  const cleanGitlab = stripNodeNoise(stripVolatile(gitlabContent));
  const cleanN8n = stripNodeNoise(stripVolatile(n8nWorkflow));

  const gitlabStr = stableStringify(cleanGitlab);
  const n8nStr = stableStringify(cleanN8n);
  const isDifferent = gitlabStr !== n8nStr;

  const changeSummary = isDifferent ? summarizeChanges(cleanGitlab, cleanN8n) : [];
  const changeSummaryText = changeSummary.map(l => `- ${l}`).join('\n');

  return {
    json: {
      workflowName,
      slug: n8nWorkflow.slug,
      projectId,
      n8nWorkflow,
      isDifferent,
      changeSummary,
      changeSummaryText,
      diffCheckedAt: new Date().toISOString(),
      debug: {
        gitlabContentWasNull: gitlabContent === null,
        gitlabKeys: cleanGitlab ? Object.keys(cleanGitlab).sort() : [],
        n8nKeys: cleanN8n ? Object.keys(cleanN8n).sort() : []
      }
    }
  };
});

const items = $input.all();

const existing = [];
const missing = [];

items.forEach((item, index) => {
  const slugData = $('Resolve GitLab subgroup path').itemMatching(index).json;

  const statusCode = item.json.statusCode;
  const isSuccess = statusCode === 200 && item.json.body && item.json.body.id;
  const isMissing = !!item.json.error || statusCode === 404;

  const currentGroupId = slugData.namespaceId || slugData.id || slugData.namespace_id;

  const record = {
    ...slugData,
    namespaceId: currentGroupId,
    namespace_id: currentGroupId,
    projectId: isSuccess ? item.json.body.id : null
  };

  if (isSuccess) {
    existing.push(record);
  } else {
    missing.push(record);
  }
});

const allProjectsExist = missing.length === 0;

return [
  {
    json: {
      allProjectsExist,
      existingCount: existing.length,
      missingCount: missing.length,
      existing,
      missing
    }
  }
];

