const items = $input.all();

function bakuTimestamp() {
  const fmt = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Baku',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hour12: false
  });
  const parts = Object.fromEntries(fmt.formatToParts(new Date()).map(p => [p.type, p.value]));
  return `${parts.year}-${parts.month}-${parts.day} ${parts.hour}:${parts.minute}:${parts.second} (Baku, GMT+4)`;
}

function findStructured(obj, depth) {
  if (!obj || typeof obj !== 'object' || depth > 6) return null;
  if (Array.isArray(obj.added) || Array.isArray(obj.changed) || Array.isArray(obj.removed) || typeof obj.summary === 'string') {
    return {
      summary: obj.summary || '',
      added: Array.isArray(obj.added) ? obj.added : [],
      changed: Array.isArray(obj.changed) ? obj.changed : [],
      removed: Array.isArray(obj.removed) ? obj.removed : []
    };
  }
  for (const key of Object.keys(obj)) {
    const val = obj[key];
    if (val && typeof val === 'object') {
      const found = findStructured(val, depth + 1);
      if (found) return found;
    }
  }
  return null;
}

function renderStructured(result) {
  const blocks = [];
  if (result.summary) blocks.push(result.summary);
  if (result.added.length) blocks.push('### Added\n' + result.added.map(l => `- ${l}`).join('\n'));
  if (result.changed.length) blocks.push('### Changed\n' + result.changed.map(l => `- ${l}`).join('\n'));
  if (result.removed.length) blocks.push('### Removed\n' + result.removed.map(l => `- ${l}`).join('\n'));
  return blocks.join('\n\n');
}

return items.map((item, index) => {
  const src = $('Split Out5').all()[index].json;
  const resp = item.json;
  const changelogExists = resp.statusCode === 200;
  const existingContent = changelogExists && typeof resp.data === 'string' ? resp.data : '';
  const timestamp = bakuTimestamp();

  let aiResult = null;
  try {
    const aiItem = $('AI Agent').all()[index];
    aiResult = aiItem && aiItem.json ? findStructured(aiItem.json, 0) : null;
  } catch (e) {
    aiResult = null;
  }

  let bodyText;
  if (aiResult && (aiResult.summary || aiResult.added.length || aiResult.changed.length || aiResult.removed.length)) {
    bodyText = renderStructured(aiResult);
  } else {
    bodyText = (src.changeSummaryText && src.changeSummaryText.length) ? src.changeSummaryText : '- Workflow updated.';
  }

  const entry = `## ${timestamp} \u2014 ${src.workflowName}\n\n${bodyText}\n\n`;

  return {
    json: {
      ...src,
      changelogExists,
      changelogContent: entry + existingContent
    }
  };
});

const input = $input.first().json;
const stdout = input.stdout || '';

if (input.code && input.code !== 0) {
  throw new Error(
    `n8n folder query exited with code ${input.code}: ${input.stderr || 'no stderr'}`
  );
}

if (!stdout.trim()) {
  throw new Error('n8n folder query returned empty stdout.');
}

let workflows;

try {
  workflows = JSON.parse(stdout);
} catch (error) {
  throw new Error(
    `Failed to parse JSON from n8n folder query: ${error.message}\n\n` +
    `stdout:\n${stdout}`
  );
}

if (!Array.isArray(workflows)) {
  throw new Error('Expected query output to be a JSON array.');
}

if (workflows.length === 0) {
  throw new Error('The query returned 0 workflows.');
}

return workflows.map(workflow => {
  const folderPath = workflow.folder_path || '';

  const folderSegments = folderPath
    .split('/')
    .filter(Boolean);

  return {
    json: {
      workflowId: workflow.workflow_id,
      workflowName: workflow.workflow_name,
      folderPath,
      folderSegments
    }
  };
});

