const config = $('Set GitLab Config').first().json;
const ROOT_FULL_PATH = config.GITLAB_ROOT_FULL_PATH;
const ROOT_GROUP_ID = config.GITLAB_ROOT_GROUP_ID;
const GITLAB_URL = config.GITLAB_URL;

const headerValue = config.GITLAB_PRIVATE_TOKEN;

const authHeaders = {
  'PRIVATE-TOKEN': headerValue,
};

const items = $input.all();
const results = [];

for (const item of items) {
  const segments = item.json.folderSegments || [];

  let currentFullPath = ROOT_FULL_PATH;
  let currentGroupId = ROOT_GROUP_ID;

  for (const segment of segments) {
    const pathSegment = segment
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .replace(/-+/g, '-');

    const nextFullPath = `${currentFullPath}/${pathSegment}`;

    currentGroupId = await resolveOrCreateGroup.call(
      this,
      nextFullPath,
      currentGroupId,
      segment
    );

    currentFullPath = nextFullPath;
  }

  results.push({
    json: {
      ...item.json,
      namespaceFullPath: currentFullPath,
      namespaceId: currentGroupId,
    },
  });
}

return results;

async function resolveOrCreateGroup(
  fullPath,
  parentId,
  originalName
) {

  const getRes = await this.helpers.httpRequest({
    method: 'GET',
    url: `${GITLAB_URL}/api/v4/groups/${encodeURIComponent(fullPath)}`,
    headers: authHeaders,
    json: true,
    ignoreHttpStatusErrors: true,
    returnFullResponse: true,
  });

  if (getRes.statusCode === 200 && getRes.body && getRes.body.id) {
    return getRes.body.id;
  }

  if (getRes.statusCode !== 404) {
    throw new Error(
      `Cannot resolve GitLab group "${fullPath}". ` +
      `HTTP ${getRes.statusCode}: ${JSON.stringify(getRes.body)}`
    );
  }

  const path = originalName
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-+/g, '-');

  let safeName = originalName
    .trim()
    .replace(/[^a-zA-Z0-9_\.\- ()]/g, '-')
    .replace(/-+/g, '-')
    .trim();

  if (!/^[a-zA-Z0-9_]/.test(safeName)) {
    safeName = 'g-' + safeName;
  }
  if (!path) {
    throw new Error(
      `Cannot create GitLab subgroup from folder name "${originalName}".`
    );
  }

  const body = {
    name: safeName || path,
    path: path,
    visibility: 'private',
    parent_id: parentId,
    project_creation_level: 'maintainer',
  };

  const createRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `${GITLAB_URL}/api/v4/groups`,
    headers: authHeaders,
    body: body,
    json: true,
    ignoreHttpStatusErrors: true,
    returnFullResponse: true,
  });

  if (createRes.statusCode === 201 && createRes.body && createRes.body.id) {
    return createRes.body.id;
  }

  if (createRes.statusCode === 400) {
    const errorBody = JSON.stringify(createRes.body);

    if (errorBody.includes('already been taken')) {
      const retryRes = await this.helpers.httpRequest({
        method: 'GET',
        url: `${GITLAB_URL}/api/v4/groups/${encodeURIComponent(fullPath)}`,
        headers: authHeaders,
        json: true,
        ignoreHttpStatusErrors: true,
        returnFullResponse: true,
      });

      if (retryRes.statusCode === 200 && retryRes.body && retryRes.body.id) {
        return retryRes.body.id;
      }
    }
  }

  throw new Error(
    `Failed to create GitLab group "${fullPath}". ` +
    `HTTP ${createRes.statusCode}: ${JSON.stringify(createRes.body)}`
  );
}

const items = $("GET workflow by ID").all();
const treeItems = $("Parse n8n tree").all();

return items.map((item, index) => {
  const original = item.json.name;

  const slug = original
    .toLowerCase()
    .replace(/[\/\\]/g, '-')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-{2,}/g, '-');

  const treeMatch =
    treeItems.find(t => t.json.workflowId === item.json.id) ||
    treeItems[index];

  const folderPath = treeMatch?.json.folderPath || '';
  const folderSegments = folderPath
    ? folderPath.split('/').filter(Boolean)
    : [];

  return {
    json: {
      ...item.json,
      originalName: original,
      slug,
      folderPath,
      folderSegments
    }
  };
});
